import org.mockito.Mockito;
import static org.junit.Assert.*;
import static org.mockito.Mockito.*;

public class AbstractIntegrator_acceptStep_TriageGen0Test {

    private TestIntegrator integrator;
    private AbstractStepInterpolator interpolator;
    private double[] y;
    private double[] yDot;

    // Concrete implementation of AbstractIntegrator to test protected method
    private static class TestIntegrator extends AbstractIntegrator {
        protected boolean statesInitialized = false;
        protected boolean resetOccurred = false;
        protected boolean isLastStep = false;
        protected List<EventState> eventsStates = new ArrayList<>();
        protected List<StepHandler> stepHandlers = new ArrayList<>();
        protected ExpandableStatefulODE equations;

        protected TestIntegrator() {
            super("TestIntegrator");
        }

        @Override
        public void integrate(ExpandableStatefulODE equations, double t) {
            this.equations = equations;
        }

        @Override
        public void integrate(FirstOrderDifferentialEquations equations, double t0, double[] y0, double t, double[] y) {
            this.equations = (ExpandableStatefulODE) equations;
        }

        @Override
        protected void computeDerivatives(double t, double[] y, double[] yDot) {
            if (equations != null) {
                equations.computeDerivatives(t, y, yDot);
            }
        }

        // Accessors for testing
        public void setStateInitialized(boolean val) { this.statesInitialized = val; }
        public boolean isStatesInitialized() { return this.statesInitialized; }
        public boolean isResetOccurred() { return this.resetOccurred; }
        public boolean isLastStep() { return this.isLastStep; }
        public void setLastStep(boolean val) { this.isLastStep = val; }
        public List<EventState> getEventsStates() { return eventsStates; }
        public List<StepHandler> getStepHandlers() { return stepHandlers; }
    }

    // Mocking EventState since it's used heavily in the logic
    public interface EventState {
        void reinitializeBegin(AbstractStepInterpolator interpolator);
        boolean evaluateStep(AbstractStepInterpolator interpolator);
        double getEventTime();
        void stepAccepted(double t, double[] y);
        boolean stop();
        boolean reset(double t, double[] y);
    }

    // Mocking ExpandableStatefulODE
    public interface ExpandableStatefulODE extends FirstOrderDifferentialEquations {
        void computeDerivatives(double t, double[] y, double[] yDot);
    }

    @Before
    public void setUp() {
        integrator = new TestIntegrator();
        interpolator = mock(AbstractStepInterpolator.class);
        y = new double[]{1.0, 2.0};
        yDot = new double[]{0.0, 0.0};

        when(interpolator.getGlobalPreviousTime()).thenReturn(0.0);
        when(interpolator.getGlobalCurrentTime()).thenReturn(1.0);
        when(interpolator.isForward()).thenReturn(true);
    }

    @Test
    public void testAcceptStep_NoEvents_NormalCompletion() {
        when(interpolator.getInterpolatedState()).thenReturn(new double[]{1.5, 2.5});

        double result = integrator.acceptStep(interpolator, y, yDot, 1.0);

        assertEquals(1.0, result, 1e-10);
        verify(interpolator).setInterpolatedTime(1.0);
        // Check if step handlers are called (if any were added)
        // In this case, none, so just verify completion
    }

    @Test
    public void testAcceptStep_InitializationLogic() {
        // Ensure reinitializeBegin is called when statesInitialized is false
        EventState mockEvent = mock(EventState.class);
        integrator.getEventsStates().add(mockEvent);
        integrator.setStateInitialized(false);

        integrator.acceptStep(interpolator, y, yDot, 1.0);

        verify(mockEvent).reinitializeBegin(interpolator);
        assertTrue(integrator.isStatesInitialized());
    }

    @Test
    public void testAcceptStep_EventTriggersStop() {
        EventState stopEvent = mock(EventState.class);
        when(stopEvent.evaluateStep(interpolator)).thenReturn(true);
        when(stopEvent.getEventTime()).thenReturn(0.5);
        when(stopEvent.stop()).thenReturn(true);

        integrator.getEventsStates().add(stopEvent);
        when(interpolator.getInterpolatedState()).thenReturn(new double[]{1.2, 2.2});

        double result = integrator.acceptStep(interpolator, y, yDot, 1.0);

        assertEquals(0.5, result, 1e-10);
        assertEquals(1.2, y[0], 1e-10);
        assertTrue(integrator.isLastStep());
    }

    @Test
    public void testAcceptStep_EventTriggersReset() {
        EventState resetEvent = mock(EventState.class);
        when(resetEvent.evaluateStep(interpolator)).thenReturn(true);
        when(resetEvent.getEventTime()).thenReturn(0.5);
        when(resetEvent.reset(anyDouble(), any(double[].class))).thenReturn(true);
        when(resetEvent.stop()).thenReturn(false);

        integrator.getEventsStates().add(resetEvent);
        when(interpolator.getInterpolatedState()).thenReturn(new double[]{1.2, 2.2});

        // Mock derivatives computation to avoid null pointer
        ExpandableStatefulODE equations = mock(ExpandableStatefulODE.class);
        integrator.integrate(equations, 0);

        double result = integrator.acceptStep(interpolator, y, yDot, 1.0);

        assertEquals(0.5, result, 1e-10);
        assertTrue(integrator.isResetOccurred());
        assertEquals(1.2, y[0], 1e-10);
    }

    @Test
    public void testAcceptStep_MultipleEvents_ChronologicalOrder() {
        EventState event1 = mock(EventState.class);
        EventState event2 = mock(EventState.class);

        // event2 occurs before event1
        when(event1.getEventTime()).thenReturn(0.8);
        when(event2.getEventTime()).thenReturn(0.4);

        when(event1.evaluateStep(interpolator)).thenReturn(true);
        when(event2.evaluateStep(interpolator)).thenReturn(true);

        when(event2.stop()).thenReturn(false);
        when(event2.reset(anyDouble(), any(double[].class))).thenReturn(false);
        when(event2.evaluateStep(interpolator)).thenReturn(false); // won't recur

        when(event1.stop()).thenReturn(false);
        when(event1.reset(anyDouble(), any(double[].class))).thenReturn(false);
        when(event1.evaluateStep(interpolator)).thenReturn(false);

        integrator.getEventsStates().add(event1);
        integrator.getEventsStates().add(event2);

        when(interpolator.getInterpolatedState()).thenReturn(new double[]{0, 0});

        integrator.acceptStep(interpolator, y, yDot, 1.0);

        // Verify event2 (0.4) was processed before event1 (0.8)
        // By checking the order of setSoftCurrentTime calls
        verify(interpolator).setSoftCurrentTime(0.4);
        verify(interpolator).setSoftCurrentTime(0.8);
    }

    @Test
    public void testAcceptStep_EventReoccurs() {
        EventState recurringEvent = mock(EventState.class);
        when(recurringEvent.evaluateStep(interpolator)).thenReturn(true).thenReturn(true).thenReturn(false);
        when(recurringEvent.getEventTime()).thenReturn(0.5);
        when(recurringEvent.stop()).thenReturn(false);
        when(recurringEvent.reset(anyDouble(), any(double[].class))).thenReturn(false);

        integrator.getEventsStates().add(recurringEvent);
        when(interpolator.getInterpolatedState()).thenReturn(new double[]{0, 0});

        integrator.acceptStep(interpolator, y, yDot, 1.0);

        // evaluateStep called: once in loop, once in while (after reset), once in while (after re-add)
        verify(recurringEvent, atLeast(3)).evaluateStep(interpolator);
    }

    @Test
    public void testAcceptStep_StepHandlers() {
        StepHandler handler = mock(StepHandler.class);
        integrator.getStepHandlers().add(handler);

        when(interpolator.getInterpolatedState()).thenReturn(new double[]{0, 0});

        integrator.acceptStep(interpolator, y, yDot, 1.0);

        // Should be called at the end of the method
        verify(handler).handleStep(eq(interpolator), anyBoolean());
    }

    @Test
    public void testAcceptStep_BackwardIntegration() {
        when(interpolator.isForward()).thenReturn(false);
        // In backward mode, orderingSign is -1. 
        // TreeSet will sort by -1 * time. 
        // If time is 0.8 and 0.4, comparison is -0.8 vs -0.4.
        // -0.8 is smaller, so 0.8 comes first in TreeSet.

        EventState event08 = mock(EventState.class);
        EventState event04 = mock(EventState.class);
        when(event08.getEventTime()).thenReturn(0.8);
        when(event04.getEventTime()).thenReturn(0.4);

        when(event08.evaluateStep(interpolator)).thenReturn(true);
        when(event04.evaluateStep(interpolator)).thenReturn(true);
        when(event08.stop()).thenReturn(true);

        integrator.getEventsStates().add(event08);
        integrator.getEventsStates().add(event04);
        when(interpolator.getInterpolatedState()).thenReturn(new double[]{0, 0});

        double result = integrator.acceptStep(interpolator, y, yDot, 1.0);

        // In backward mode, the "first" event is the one with the highest time (closest to current)
        // but the comparator uses orderingSign * time.
        // -0.8 < -0.4, so event08 is first.
        assertEquals(0.8, result, 1e-10);
    }

    @Test
    public void testAcceptStep_PrecisionEnd() {
        // Test the Precision.equals(currentT, tEnd, 1) logic
        double tEnd = 1.0000000000001;
        when(interpolator.getGlobalCurrentTime()).thenReturn(1.0);
        when(interpolator.getInterpolatedState()).thenReturn(new double[]{0, 0});

        integrator.acceptStep(interpolator, y, yDot, tEnd);
        // This verifies the code path reaches the end and handles isLastStep logic
    }
}
